/**
 * buildBulk.js  — generates all 5 bulk law files in one run
 * node backend/data/buildBulk.js
 */
'use strict';
const fs   = require('fs');
const path = require('path');
const DIR  = __dirname;

/* ── helper ─────────────────────────────────────────────── */
function e(act,short,sec,title,desc,ch,cht,cat,...kw){
  return {act,act_short:short,section:String(sec),section_title:title,
          section_desc:desc,chapter:String(ch),chapter_title:cht,
          category:cat,keywords:kw.flat()};
}
function save(name,arr){
  fs.writeFileSync(path.join(DIR,name),JSON.stringify(arr,null,1),'utf8');
  console.log(`✓  ${name.padEnd(40)} ${arr.length} entries`);
}

/* ═══════════════════════════════════════════════════════════
   FILE 1 — bulk_civil_laws.json   (TPA, IEA, Arbitration,
   Succession, Specific Relief, Limitation, CPC rules)
   ═══════════════════════════════════════════════════════════ */
const civil = [];

// ── Transfer of Property Act 1882 ────────────────────────
const TPA_DATA = [
  ["6A","What cannot be transferred","A right of re-entry for breach of condition cannot be transferred to anyone other than the owner of the property affected by the condition. A right to sue cannot be transferred. An easement cannot be transferred apart from the dominant heritage. A public office cannot be transferred. A stipend attached to military, naval, air-force, civil service or pension cannot be transferred. A mere right to sue for damages in tort cannot be transferred.","1","What may be transferred","Property Law",["TPA transfer restriction right to sue easement public office pension cannot transfer section 6A"]],
  ["9","Oral transfers","A transfer of property may be made without writing in every case in which a writing is not expressly required by law. However, under S.54 TPA sale of immovable property of value Rs 100 or more must be by registered instrument. Under S.105 TPA lease for more than one year must be in writing. Under S.123 TPA gift of immovable property must be by registered instrument.","1","Transfer of Property","Property Law",["TPA oral transfer no writing required exceptions sale lease gift registered instrument section 9"]],
  ["14","Rule against perpetuities","No transfer of property can operate to create an interest which is to take effect after the lifetime of one or more persons living at the date of such transfer, and the minority of some person who shall be in existence at the expiration of that period, and to whom, if he attains full age, the interest created is to belong. Unlike English rule, Indian perpetuity period is life in being + 18 years.","1","Transfer of Property","Property Law",["TPA rule against perpetuities life in being 18 years interest future section 14 English difference"]],
  ["23","Conditions restraining enjoyment","Where property is transferred subject to a condition or limitation which absolutely restrains the transferee from parting with or disposing of his interest, the condition is void. A partial restraint is valid — restraint for a limited time is not void (Rosher v. Rosher not followed in India). A pre-emption clause in a lease is not a restraint on alienation.","1","Transfer of Property","Property Law",["TPA restraint alienation void partial restraint valid limited time pre-emption lease section 23"]],
  ["40","Burden of obligations imposing restrictions on use of land","Where a third person is entitled to the benefit of an obligation arising out of contract and annexed to the ownership of immovable property, such obligation may be enforced against a transferee with notice. Restrictive covenants run with the land and bind successors in title who have notice. The Tulk v. Moxhay principle: original covenantor's negative obligation binds successors.","2","Transfer of Immoveable Property","Property Law",["TPA restrictive covenant notice runs with land Tulk v Moxhay successors title obligation section 40"]],
  ["44","Transfer by one co-owner","Where one of two or more co-owners of immoveable property transfers his share of such property or any interest therein, the transferee acquires, as to the share or interest so transferred, the transferor's right to joint possession or other common or part enjoyment of the property, and to enforce a partition of the same. A co-owner can sell his undivided share without consent of other co-owners.","2","Transfer of Immoveable Property","Property Law",["TPA co-owner transfer undivided share partition section 44 consent not required joint possession"]],
  ["48","Priority of rights created by transfer","Where a person purports to create by transfer at different times rights in or over the same immoveable property, and such rights cannot all exist or be exercised to their full extent together, each later created right shall be subject to the rights previously created — Prior tempore potior jure (first in time, stronger in law). Exception: later transferee without notice of prior transfer may get priority under S.41 and S.48.","2","Transfer of Immoveable Property","Property Law",["TPA priority prior tempore potior jure first in time section 48 notice exception later transferee"]],
  ["52","Lis pendens doctrine","During the pendency of any suit or proceeding in which any right to immoveable property is directly and specifically in question, the property cannot be transferred or otherwise dealt with by any party to the suit so as to affect the rights of any other party. Transfer during lis pendens is not void but takes effect subject to the rights of parties in the suit.","2","Transfer of Immoveable Property","Property Law",["TPA lis pendens doctrine transfer pending suit section 52 not void subject to rights parties"]],
  ["55A","Rights and liabilities — Agreement to sell","A contract for the sale of immoveable property does not itself create any interest in the property. The vendor must show a valid title. The vendee is entitled to possession on completion. Agreement to sell does not pass title — this principle is central to understanding when title passes. Registration of agreement to sell is not mandatory (unless it creates an interest in property).","3","Sales of Immoveable Property","Property Law",["TPA agreement to sell no interest title passes completion registration section 55A"]],
  ["58A","Different types of mortgage","Simple mortgage (S.58(b)) — personal covenant + charge on property, no possession. Mortgage by conditional sale (S.58(c)) — ostensible sale with defeasance clause. Usufructuary mortgage (S.58(d)) — possession + usufruct to mortgagee, no personal covenant. English mortgage (S.58(e)) — absolute transfer with covenant to re-convey. Mortgage by deposit of title deeds (S.58(f)) — equitable mortgage, no registration needed. Anomalous mortgage (S.58(g)) — any other form.","4","Mortgages","Property Law",["TPA mortgage types simple usufructuary English equitable anomalous conditional sale section 58 differences"]],
  ["63","Accession to mortgaged property","Where mortgaged property in possession of the mortgagee has during the continuance of the mortgage, received any accession, the mortgagee, in the absence of a contract to the contrary, shall, upon redemption, be liable to deliver to the mortgagor such accession as well as the mortgaged property. Accession here means any improvement or addition to the property.","4","Mortgages","Property Law",["TPA accession mortgaged property mortgagee possession deliver redemption section 63 improvement addition"]],
  ["65A","Mortgage of future property","Mortgage made by the mortgagor of property to be acquired in future becomes effective when such property is acquired and the mortgagee takes possession. The doctrine of feeding the grant by estoppel applies — the mortgagor cannot deny that property belongs to him once he acquires it.","4","Mortgages","Property Law",["TPA future property mortgage section 65A estoppel feeding grant mortgagor acquired"]],
  ["69","Sale without intervention of court","A mortgagee who holds a mortgage by deposit of title deeds executed after the commencement of this Act, and in whose favour power of sale without intervention of court has been conferred by the mortgage-deed may, in default of payment of mortgage-money when due, sell the mortgaged property or any part thereof. Power of sale is exercised without court intervention.","4","Mortgages","Property Law",["TPA power of sale without court mortgagee title deeds section 69 default payment mortgage"]],
  ["90","Foreclosure","Mortgagor in default gives mortgagee right to extinguish the equity of redemption. Foreclosure means mortgagee seeking decree that mortgagor shall be absolutely debarred of his right to redeem. Applies to English mortgage and mortgage by conditional sale. Not available for usufructuary mortgage. Foreclosure decree is in two stages: preliminary (sets time to pay) and final (bars redemption).","4","Mortgages","Property Law",["TPA foreclosure equity of redemption English mortgage conditional sale preliminary final decree section 67 bar redemption"]],
  ["106","Duration of certain leases","In the absence of a contract or local law, a lease of agricultural or manufacturing purpose is deemed to be a lease from year to year terminable on the part of either lessor or lessee by fifteen days' notice. A lease of immoveable property for any other purpose is deemed a monthly lease terminable by fifteen days' notice expiring with the end of a month of the tenancy.","5","Leases","Property Law",["TPA lease duration year to year monthly fifteen days notice agricultural manufacturing section 106"]],
  ["107A","Leases how made — registration requirements","A lease of immoveable property from year to year, or for any term exceeding one year, or reserving a yearly rent, can only be made by a registered instrument. All other leases of immoveable property may be made either by a registered instrument or by oral agreement accompanied by delivery of possession. An unregistered lease for more than one year is inadmissible as evidence but the tenancy can be proved by conduct.","5","Leases","Property Law",["TPA lease registration one year registered instrument oral delivery possession inadmissible section 107A"]],
  ["108B","Lessee's rights — quiet enjoyment","The lessee is entitled to be put in possession of the property; and to enjoy the property without disturbance by the lessor so long as the lessee pays the rent and performs the conditions of the lease. The doctrine of quiet enjoyment means the lessor must not disturb lessee's possession. Breach entitles lessee to claim damages or terminate lease.","5","Leases","Property Law",["TPA quiet enjoyment lessee right possession rent conditions disturbance lessor damages section 108B"]],
  ["109","Rights of lessor's transferee","If the lessor transfers the property leased, or any part thereof, or any part of his interest therein, the transferee, in the absence of a contract to the contrary, shall possess all the rights, and, if the lessee so elects, be subject to all the liabilities of the lessor as to the property or part transferred. The principle that the lease runs with the land — privity of estate.","5","Leases","Property Law",["TPA transferee lessor rights lease runs with land privity estate section 109 elect liabilities"]],
  ["113","Waiver of forfeiture","Where a lessor, knowing of a cause of forfeiture, accepts rent or distress for rent, or otherwise acts in a manner consistent with the continuance of the lease, he shall be deemed to have waived the forfeiture. Waiver of forfeiture is implied from conduct. Once waived, lessor cannot rely on same forfeiture. But waiver does not prevent lessor from relying on future breaches.","5","Leases","Property Law",["TPA waiver forfeiture lessor accepts rent conduct section 113 implied waiver same breach future"]],
  ["114","Relief against forfeiture for non-payment of rent","Where a lease of immoveable property has been determined by forfeiture for non-payment of rent, and the lessor sues to eject the lessee, if, at the hearing of the suit, the lessee pays or tenders to the lessor the rent in arrear, together with the costs of the suit, the court may, in lieu of making a decree for ejectment, pass an order relieving the lessee against the forfeiture.","5","Leases","Property Law",["TPA relief forfeiture non-payment rent section 114 court ejectment pays arrear costs order"]],
  ["120","Improvements made by lessee","If a lessee makes any improvement to the property leased, with the written consent of the lessor, and the lease subsequently determines otherwise than by the lessee's own act, the lessee is entitled to receive on quitting the property such compensation for the improvement as is provided in the lease or as the court thinks just. Improvements without consent — no compensation.","5","Leases","Property Law",["TPA lessee improvements written consent compensation quitting property section 120 lease determines court"]],
  ["131","Transfer of actionable claim — Notice","The transfer of an actionable claim (S.130) is complete on execution of the instrument but notice to the debtor is important for priority. Where the debtor has notice of an earlier transfer, subsequent payment to the original creditor does not discharge debt. The transferee has all rights to enforce the claim in his own name after notice.","8","Transfer of Actionable Claims","Property Law",["TPA actionable claim notice debtor priority section 131 payment discharge transferee enforce"]],
];
TPA_DATA.forEach(([sec,title,desc,ch,cht,cat,kw])=>civil.push(e("Transfer of Property Act, 1882","TPA",sec,title,desc,ch,cht,cat,kw)));

// ── Indian Evidence Act 1872 ─────────────────────────────
const IEA_DATA = [
  ["1","Short title, extent and commencement","The Indian Evidence Act, 1872 extends to the whole of India, except the State of Jammu and Kashmir. It applies to all judicial proceedings in or before any court, including courts martial, other than courts martial convened under the Army Act, the Naval Discipline Act and the Indian Navy Discipline Act. It also applies to arbitration proceedings where a reference is made by a court.","1","Preliminary","Evidence Law",["IEA application India courts judicial proceedings army naval arbitration section 1"]],
  ["3","Interpretation clause — Fact, relevant fact, evidence","'Fact' means and includes any thing, state of things, or relation of things, capable of being perceived by the senses; and any mental condition of which any person is conscious. 'Relevant' means one fact is said to be relevant to another when the one is connected with the other in any way mentioned in sections 5 to 55. 'Evidence' means and includes oral statements which the court permits or requires to be made before it by witnesses; documents including electronic records.","1","Preliminary","Evidence Law",["IEA fact relevant evidence definition section 3 mental condition perceived senses documents electronic records oral"]],
  ["4","May presume, shall presume, conclusive proof","'May presume' — the court may either regard a fact as proved unless and until it is disproved, or require it to be proved. 'Shall presume' — the court shall regard a fact as proved unless and until it is disproved. 'Conclusive proof' — when one fact is declared by this Act to be conclusive proof of another, the court shall, on proof of the one fact, regard the other as proved and shall not allow evidence to be given for the purpose of disproving it. Example: S.112 — birth during marriage is conclusive proof of legitimacy.","1","Preliminary","Evidence Law",["IEA may presume shall presume conclusive proof section 4 court fact proved disproved S112 legitimacy"]],
  ["6","Res gestae — Facts forming part of same transaction","Facts which, though not in issue, are so connected with a fact in issue as to form part of the same transaction, are relevant, whether they occurred at the same time and place or at different times and places. Res gestae means 'things done' — spontaneous exclamations during or immediately after an event. Applies to statements made under immediate pressure of the event. Distinction from hearsay: res gestae statements are admissible as original evidence.","2","Relevancy of Facts","Evidence Law",["IEA res gestae section 6 same transaction spontaneous exclamation immediate pressure original evidence hearsay distinction"]],
  ["7","Facts which are occasions, causes or effects","Facts which are the occasion, cause, or effect, immediate or otherwise, of relevant facts, or facts in issue, or which constitute the state of things under which they happened, or which afforded an opportunity for their occurrence or transaction, are relevant. Example: the opportunity for the accused to commit the crime is relevant.","2","Relevancy of Facts","Evidence Law",["IEA occasion cause effect relevant facts section 7 opportunity state of things constitute happened"]],
  ["8","Motive, preparation and previous or subsequent conduct","Any fact is relevant which shows or constitutes a motive or preparation for any fact in issue or relevant fact. The conduct of any party, or of any agent to any party, to any suit or proceeding, in reference to such suit or proceeding, or in reference to any fact in issue therein or relevant thereto, and the conduct of any person an offence against whom is the subject of any proceeding, is relevant, if such conduct influences or is influenced by any fact in issue or relevant fact.","2","Relevancy of Facts","Evidence Law",["IEA motive preparation conduct section 8 party agent suit proceeding influences relevant fact"]],
  ["9","Facts necessary to explain or introduce","Facts necessary to explain or introduce a fact in issue or relevant fact, or which support or rebut an inference suggested by a fact in issue or relevant fact, or which establish the identity of any thing or person whose identity is relevant, or fix the time or place at which any fact in issue or relevant fact happened, or which show the relation of parties by whom any such fact was transacted, are relevant in so far as they are necessary for that purpose.","2","Relevancy of Facts","Evidence Law",["IEA explain introduce identity time place relation parties section 9 rebut inference"]],
  ["11","Facts inconsistent with or highly probable","Facts not otherwise relevant are relevant if they are inconsistent with any fact in issue or relevant fact; or if by themselves or in connection with other facts they make the existence or non-existence of any fact in issue or relevant fact highly probable or improbable.","2","Relevancy of Facts","Evidence Law",["IEA inconsistent highly probable improbable section 11 relevant facts issue"]],
  ["13","Facts relevant when right or custom in question","Where the question is as to the existence of any right or custom, the following facts are relevant: any transaction by which the right or custom in question was created, claimed, modified, recognised, asserted, or denied, or which was inconsistent with its existence; particular instances in which the right or custom was claimed, recognised, or exercised, or in which its exercise was disputed, asserted, or departed from.","2","Relevancy of Facts","Evidence Law",["IEA right custom section 13 transaction created claimed modified recognised instances particular"]],
  ["14","Facts showing state of mind or body","Facts showing the existence of any state of mind, such as intention, knowledge, good faith, negligence, rashness, ill-will or good-will towards any particular person, or showing the existence of any state of body or bodily feeling, are relevant when the existence of any such state of mind or body is in issue or relevant.","2","Relevancy of Facts","Evidence Law",["IEA state of mind body section 14 intention knowledge good faith negligence rashness ill-will relevant"]],
  ["15","Facts bearing on question whether act was accidental or intentional","When there is a question whether an act was accidental or intentional, or done with a particular knowledge or intention, the fact that such act formed part of a series of similar occurrences, in each of which the person doing the act was concerned, is relevant. Doctrine of similar facts — series of similar acts shows intention/knowledge.","2","Relevancy of Facts","Evidence Law",["IEA accidental intentional similar facts section 15 series occurrences knowledge intention doctrine"]],
  ["16","Existence of course of business","When there is a question whether a particular act was done, the existence of any course of business, according to which it naturally would have been done, is a relevant fact. Example: if a letter was posted according to usual office procedure, it is presumed to have been received.","2","Relevancy of Facts","Evidence Law",["IEA course of business section 16 particular act posted letter presumed received office procedure"]],
  ["17","Admission defined","An admission is a statement, oral or documentary or contained in electronic form, which suggests any inference as to any fact in issue or relevant fact, and which is made by any of the persons, and under the circumstances, hereinafter mentioned. Admissions are not conclusive proof — they shift the burden. An admission must be a clear, unambiguous statement.","3","Admissions","Evidence Law",["IEA admission defined section 17 oral documentary electronic inference fact issue burden shift unambiguous"]],
  ["18","Admission by party to proceeding","Statements made by a party to the proceeding, or by an agent to any such party, whom the court regards, in the circumstances of the case, as expressly or impliedly authorised by him to make them, are admissions. Admissions by co-defendants are not admissible against each other unless made in one's presence and not denied. A party is bound by his own admissions.","3","Admissions","Evidence Law",["IEA admission party agent authorised section 18 co-defendants presence not denied bound"]],
  ["21","Proof of admissions against persons making them","Admissions may be proved against the person who makes them or his representative in interest. An admission by a party to a suit can be used against that party but not in his favour. Exception: a party may prove his own statement if it is part of a longer conversation to show the full context (S.21 IEA).","3","Admissions","Evidence Law",["IEA proof admission against person section 21 party suit own statement context"]],
  ["24","Confession caused by inducement etc.","A confession made by an accused person is irrelevant in a criminal proceeding if the making of the confession appears to the court to have been caused by any inducement, threat or promise having reference to the charge against the accused person, proceeding from a person in authority, and sufficient in the opinion of the court to give the accused person grounds which would appear to him reasonable for supposing that by making it he would gain any advantage or avoid any evil in reference to the proceedings against him.","3","Admissions","Evidence Law",["IEA confession inducement threat promise accused section 24 irrelevant authority advantage evil reasonable criminal"]],
  ["26","Confession by accused while in custody of police","No confession made by any person whilst he is in the custody of a police officer, unless it be made in the immediate presence of a Magistrate, shall be proved as against such person. S.26 extends the bar of S.25 to co-accused confessions made in police custody. The only exception: confession made before a Magistrate even while in police custody is admissible.","3","Admissions","Evidence Law",["IEA confession police custody section 26 Magistrate co-accused admissible exception bar section 25"]],
  ["29","Confession otherwise relevant not to become irrelevant because of promise","If such a confession is otherwise relevant, it does not become irrelevant merely because it was made under a promise of secrecy, or in consequence of a deception practised on the accused person for the purpose of obtaining it, or when he was drunk, or because it was made in answer to questions which he need not have answered, whatever may have been the form of those questions.","3","Admissions","Evidence Law",["IEA confession relevant section 29 promise secrecy deception drunk questions voluntary"]],
  ["33","Relevancy of certain evidence for proving in subsequent proceeding","Evidence given by a witness in a judicial proceeding, or before any person authorised by law to take it, is relevant for the purpose of proving the truth of the facts which it states in any subsequent judicial proceeding, or in a later stage of the same judicial proceeding, when the witness is dead, cannot be found, incapable of giving evidence, kept out of the way by adverse party, or exempted from giving evidence.","3","Admissions","Evidence Law",["IEA evidence subsequent proceeding section 33 witness dead cannot found incapable kept out way earlier testimony"]],
  ["34","Entries in books of account","Entries in books of account, including those maintained in an electronic form, regularly kept in the course of business, are relevant whenever they refer to a matter into which the court has to inquire, but such statements shall not alone be sufficient evidence to charge any person with liability. Books of account are relevant but not conclusive — need corroboration.","4","Oral Evidence","Evidence Law",["IEA books of account electronic regularly kept business section 34 relevant not conclusive corroboration charge"]],
  ["36","Relevancy of statements in maps, charts and plans","Statements of facts in issue or relevant facts, made in published maps or charts generally offered for public sale, or in maps or plans made under the authority of the Central Government or any State Government, as to matters usually represented or stated in such maps, charts or plans, are themselves relevant facts.","4","Oral Evidence","Evidence Law",["IEA maps charts plans published section 36 government authority statements relevant facts"]],
  ["39","What evidence to be given when statement forms part of conversation etc.","When any statement of which evidence is given forms part of a longer statement, or of a conversation or part of an isolated document, or is contained in a document which forms part of a book, or of a connected series of letters or papers, evidence shall be given of so much and no more of the statement, conversation, document, book, or series of letters or papers as the court considers necessary in that particular case to the full understanding of the nature and effect of the statement.","4","Oral Evidence","Evidence Law",["IEA statement part conversation document book section 39 full understanding context so much no more"]],
  ["40","Previous judgments relevant to bar second suit or trial","The existence of any judgment, order or decree which by law prevents any court from taking cognizance of a suit or holding a trial, is a relevant fact when the question is whether such court ought to take cognizance of such suit or to hold such trial. Res judicata under S.11 CPC bars re-trial — S.40 IEA makes the earlier judgment relevant evidence.","5","Judgments","Evidence Law",["IEA previous judgment relevant section 40 res judicata bar second suit cognizance S11 CPC"]],
  ["43","Judgments in cases not binding — when relevant","Judgments, orders or decrees other than those mentioned in sections 40, 41 and 42 are irrelevant, unless the existence of such judgment, order or decree, is a fact in issue, or is relevant under some other provision of this Act. A civil judgment between A and B is generally not relevant in a criminal case between State and B on the same facts (different parties, different proceedings).","5","Judgments","Evidence Law",["IEA judgment irrelevant section 43 exceptions fact in issue different parties criminal civil binding"]],
  ["46","Expert opinion — When binding on court","Expert opinions are admissible under S.45 but courts are not bound by them. The court can: agree entirely with expert; disagree on specific points; prefer one expert over another. Expert must be specially skilled — not merely having general knowledge. Expert must give reasons for opinion. Expert's opinion on matters of law is not admissible — law is for the court.","5","Judgments","Evidence Law",["IEA expert opinion section 45 46 not binding court reasons skilled law not admissible prefer disagree"]],
  ["47A","Opinion on electronic signature","When the court has to form an opinion as to the electronic signature of any person, the opinion of the Certifying Authority which has issued the Electronic Signature Certificate is a relevant fact. This provision gives statutory recognition to the role of Certifying Authorities under the IT Act 2000.","5","Opinion of Third Persons","Evidence Law",["IEA electronic signature opinion Certifying Authority section 47A IT Act 2000 digital certificate relevant"]],
  ["52","Character in civil cases","In civil cases the fact that the character of any person concerned is such as to render probable or improbable any conduct imputed to him is irrelevant, except in so far as such character appears from facts otherwise relevant. Character evidence is generally inadmissible in civil cases except through other relevant facts.","5","Character","Evidence Law",["IEA character civil cases section 52 irrelevant probable conduct person except relevant facts"]],
  ["53","In criminal cases previous good character relevant","In criminal proceedings the fact that the person accused is of a good character is relevant. The prosecution cannot lead evidence of bad character unless the accused has first put his character in issue by claiming good character (rebuttal). Previous convictions are relevant for sentencing (S.54 IEA).","5","Character","Evidence Law",["IEA good character criminal accused section 53 relevant prosecution bad character rebuttal put in issue"]],
  ["56","Fact judicially noticeable need not be proved","No fact of which the court will take judicial notice need be proved. Courts take judicial notice of: all laws in force in India; articles of war; course of proceeding of Parliament and Legislatures; seals of courts; public holidays; territorial extent of India; death of head of state.","6","Oral Evidence","Evidence Law",["IEA judicial notice section 56 laws course proceeding Parliament seals courts public holidays need not prove"]],
  ["57","Facts of which court must take judicial notice","The court shall take judicial notice of: all laws in force in India; all public Acts passed by Parliament and State Legislatures; course of proceedings of Parliament; existence, title and national flag of every State; marks of jurisdiction; division of time; geography and natural features of India; commencement of every judicial year.","6","Oral Evidence","Evidence Law",["IEA mandatory judicial notice section 57 laws Parliament Acts geography time division title national flag India"]],
  ["58","Facts admitted need not be proved","No fact need be proved in any proceeding which the parties thereto or their agents agree to admit at the hearing, or which, before the hearing, they agree to admit by any writing under their hands. The court may, in its discretion, require the facts admitted to be proved otherwise than by such admissions.","6","Oral Evidence","Evidence Law",["IEA admitted facts need not proved section 58 parties agree hearing writing discretion court"]],
  ["59","Proof of facts by oral evidence","All facts, except the contents of documents or electronic records, may be proved by oral evidence. Oral evidence must be direct: what you saw must be proved by person who saw it; what you heard by person who heard it; what you perceived by your senses by person who perceived it; opinion by person holding opinion.","7","Oral Evidence","Evidence Law",["IEA oral evidence section 59 all facts direct eyewitness hearsay senses perception document exception"]],
  ["60","Oral evidence must be direct","Oral evidence must, in all cases whatever, be direct; that is to say: if it refers to a fact which could be seen, it must be the evidence of a witness who says he saw it; if it refers to a fact which could be heard, it must be the evidence of a witness who says he heard it. The hearsay rule excludes indirect oral evidence except under specific exceptions (S.32 IEA, etc.).","7","Oral Evidence","Evidence Law",["IEA direct oral evidence section 60 hearsay rule saw heard perceived exceptions section 32"]],
  ["61","Proof of contents of documents","The contents of documents may be proved either by primary evidence or by secondary evidence. Primary: the document itself produced for inspection. Secondary: certified copies, copies made from original, oral accounts of contents. Electronic records: S.65B certificate required.","8","Documentary Evidence","Evidence Law",["IEA proof documents section 61 primary secondary evidence certified copy oral account electronic 65B"]],
  ["64","Primary evidence","Primary evidence means the document itself produced for the inspection of the court. Where a document is executed in several parts, each part is primary evidence of the document. Where a document is executed in counterpart, each counterpart being executed by one or some of the parties only, each counterpart is primary evidence as against the parties executing it.","8","Documentary Evidence","Evidence Law",["IEA primary evidence section 64 document itself inspection court parts counterpart"]],
  ["65","Cases in which secondary evidence relating to documents may be given","Secondary evidence may be given of the existence, condition or contents of a document when: the original is shown or appears to be in possession of the adverse party; existence, condition or contents of original have been proved to be admitted; original has been destroyed or lost; original is not easily movable; original is a public document; original is document of which a certified copy is permitted by this Act; original consists of numerous accounts or other documents.","8","Documentary Evidence","Evidence Law",["IEA secondary evidence section 65 original possession adverse party destroyed lost public document certified copies numerous accounts"]],
  ["66","Rules as to notice to produce","Secondary evidence of the contents of the documents referred to in section 65, clause (a), shall not be given unless the party proposing to give such secondary evidence has previously given to the party in whose possession or power the document is, such notice to produce it as is prescribed by law; and if no notice is prescribed by law, then such notice as the court considers reasonable under the circumstances.","8","Documentary Evidence","Evidence Law",["IEA notice to produce section 66 secondary evidence possession party prescribed reasonable court"]],
  ["67","Proof of signature and handwriting of person alleged to have signed or written document","If a document is alleged to be signed or to have been written wholly or in part by any person, the signature or the handwriting of so much of the document as is alleged to be in that person's handwriting must be proved to be in his handwriting. Proof methods: witness testimony, comparison by court, expert opinion, admission by party.","8","Documentary Evidence","Evidence Law",["IEA handwriting signature section 67 proof alleged written witness comparison expert admission"]],
  ["74","Public documents","Documents forming the acts or records of the acts: of the sovereign authority; of official bodies and tribunals; of public officers — legislative, judicial and executive — of any part of India or of the Commonwealth or of a foreign country. Official publications of foreign governments; certified copies of public records are public documents.","9","Public Documents","Evidence Law",["IEA public documents section 74 sovereign authority official records legislative judicial executive India Commonwealth foreign"]],
  ["76","Certified copies of public documents","Every public officer having the custody of a public document, which any person has a right to inspect, shall give that person on demand a copy of it on payment of the legal fees therefor, together with a certificate written at the foot of such copy that it is a true copy of such document or part thereof, as the case may be, and such certificate shall be dated and subscribed by such officer with his name and official title.","9","Public Documents","Evidence Law",["IEA certified copies section 76 public document officer custody right inspect payment certificate true copy official"]],
  ["79","Presumption as to genuineness of certified copies","The court shall presume to be genuine every document purporting to be a certificate, certified copy or other document, which is by law declared to be admissible as evidence of any particular fact and which purports to be duly certified by any officer of the Central Government or of a State Government.","10","Presumptions","Evidence Law",["IEA presumption genuineness certified copies section 79 government officer authentic admissible certificate"]],
  ["80","Presumption as to documents produced as record of evidence","Whenever any document is produced before any court, purporting to be a record or memorandum of the evidence, or of any part of the evidence, given by a witness in a judicial proceeding or before any officer authorised by law to take such evidence, the court shall presume that the document is genuine, that any statement made therein in accordance with law, and that such evidence, statement or confession was duly taken.","10","Presumptions","Evidence Law",["IEA presumption record evidence section 80 judicial proceeding genuine authorised law taken"]],
  ["81","Presumption as to Gazettes, newspapers","The court shall presume the genuineness of every document purporting to be the London Gazette, the Official Gazette, or the Government Gazette of any State, or to be a newspaper or journal, or to be a copy of a private Act of Parliament of the United Kingdom, printed by the Queen's Printer, and of every document purporting to be a document directed by any law to be kept by any person, if such document is kept substantially in the form required by law.","10","Presumptions","Evidence Law",["IEA Gazette newspaper presumption section 81 Official Gazette State genuineness private Act Parliament"]],
  ["83","Presumption as to maps or plans","The court shall presume that maps or plans purporting to be made by the authority of the Central Government or any State Government were so made and are accurate; but maps or plans made for the purposes of any cause must be proved to be accurate.","10","Presumptions","Evidence Law",["IEA maps plans presumption section 83 Central State Government accurate cause purposes proof"]],
  ["85","Presumption as to powers of attorney","The court shall presume that every document purporting to be a power of attorney, and to have been executed before, and authenticated by, a notary public or any court, Judge, Magistrate, Indian Consul or Vice-Consul, or representative of the Central Government, was so executed and authenticated.","10","Presumptions","Evidence Law",["IEA power of attorney presumption section 85 notary public court Judge Magistrate executed authenticated"]],
  ["89","Presumption as to due execution of documents not produced","The court shall presume that every document called for and not produced after notice to produce has been attested, stamped and executed in the manner required by law. The party who does not produce the document after notice has to bear adverse presumptions.","10","Presumptions","Evidence Law",["IEA presumption due execution section 89 document not produced notice attested stamped executed law adverse"]],
  ["91","Evidence of terms of contracts, grants and other dispositions of property reduced to documentary form — Parol evidence rule","When the terms of a contract, or of a grant, or of any other disposition of property, have been reduced to the form of a document, and in all cases in which any matter is required by law to be reduced to the form of a document, no evidence shall be given in proof of the terms of such contract, grant or other disposition of property, or of such matter, except the document itself, or secondary evidence of its contents. Parol evidence rule — oral evidence cannot contradict written contract.","11","Exclusion of Oral by Documentary Evidence","Evidence Law",["IEA parol evidence rule section 91 written contract document terms oral cannot contradict grant disposition"]],
  ["92","Exclusion of evidence of oral agreement","When the terms of any such contract, grant or other disposition of property, or any matter required by law to be reduced to the form of a document, have been proved according to the last section, no evidence of any oral agreement or statement shall be admitted, as between the parties to any such instrument or their representatives in interest, for the purpose of contradicting, varying, adding to, or subtracting from, its terms. Exceptions: collateral agreements, ambiguity, subsequent oral agreement, fraud.","11","Exclusion of Oral by Documentary Evidence","Evidence Law",["IEA exclude oral agreement section 92 written instrument contradict vary add subtract collateral ambiguity fraud exception"]],
  ["93","Exclusion of evidence to explain or amend ambiguous document","When the language used in a document is, on its face, ambiguous or defective, evidence may not be given of facts which would show its meaning or supply its defects. Latent ambiguity (S.96): where document on its face is clear but evidence shows two persons fit description, evidence to show which is meant is admissible. Patent ambiguity (S.93): document itself is ambiguous — cannot be cured by extrinsic evidence.","11","Exclusion of Oral by Documentary Evidence","Evidence Law",["IEA ambiguous document section 93 96 patent latent ambiguity extrinsic evidence meaning defect"]],
  ["101","Burden of proof in general","Whoever desires any court to give judgment as to any legal right or liability dependent on the existence of facts which he asserts, must prove that those facts exist. When a person is bound to prove the existence of any fact, it is said that the burden of proof lies on that person. The burden of proof as to any particular fact lies on that person who wishes the Court to believe in its existence.","12","Burden of Proof","Evidence Law",["IEA burden of proof section 101 legal right liability facts assert prove judgment general rule"]],
  ["103","Burden of proof as to particular fact","The burden of proof as to any particular fact lies on that person who wishes the court to believe in its existence, unless it is provided by any law that the proof of that fact shall lie on any particular person. Reverse burden: NDPS (S.35, S.54), PMLA (S.24), Dowry Death (S.113B IEA).","12","Burden of Proof","Evidence Law",["IEA burden of proof particular fact section 103 reverse burden NDPS PMLA dowry death S113B"]],
  ["105","Burden of proving exception","When a person is accused of any offence, the burden of proving the existence of circumstances bringing the case within any of the General Exceptions in the Indian Penal Code, or within any special exception or proviso contained in any other part of the same Code, or in any law defining the offence, is upon him, and the court shall presume the absence of such circumstances. Accused must prove insanity (S.84 IPC), self-defence on balance of probabilities.","12","Burden of Proof","Evidence Law",["IEA burden exception section 105 accused general exceptions IPC insanity self-defence balance probabilities court presume absence"]],
  ["106","Burden of proving fact especially within knowledge","When any fact is especially within the knowledge of any person, the burden of proving that fact is upon him. Example: where a person travels without ticket, burden to prove he had a valid ticket is on him. Applicable in poisoning cases where husband had exclusive control over food.","12","Burden of Proof","Evidence Law",["IEA specially within knowledge section 106 burden proving ticket poisoning husband exclusive control food"]],
  ["107","Burden of proving death of person known to have been alive within thirty years","When the question is whether a man is alive or dead, and it is shown that he was alive within thirty years, the burden of proving that he is dead is on the person who affirms it. Converse: S.108 — if not heard of for seven years, presumed dead.","12","Burden of Proof","Evidence Law",["IEA alive dead burden section 107 thirty years prove death person affirms S108 seven years presumed"]],
  ["109","Burden of proof as to relationship","When the question is whether persons are partners, landlord and tenant, or principal and agent, and it has been shown that they have been acting as such, the burden of proving that they do not stand, or have ceased to stand, to each other in those relationships respectively, is on the person who affirms it.","12","Burden of Proof","Evidence Law",["IEA relationship section 109 partner landlord tenant principal agent presumption burden prove ceased"]],
  ["110","Burden of proof as to ownership","When the question is whether any person is owner of anything of which he is shown to be in possession, the burden of proving that he is not the owner is on the person who affirms that he is not the owner.","12","Burden of Proof","Evidence Law",["IEA ownership possession section 110 burden prove not owner person affirms possession"]],
  ["112","Birth during marriage conclusive proof of legitimacy","The fact that any person was born during the continuance of a valid marriage between his mother and any man, or within two hundred and eighty days after its dissolution, the mother remaining unmarried, shall be conclusive proof that he is the legitimate son of that man, unless it can be shown that the parties to the marriage had no access to each other at any time when he could have been begotten. DNA evidence can now rebut this presumption (SC decision).","12","Burden of Proof","Evidence Law",["IEA legitimacy conclusive proof section 112 born marriage 280 days dissolution no access DNA rebut"]],
  ["113A","Presumption as to abetment of suicide by a married woman","When the question is whether the commission of suicide by a woman had been abetted by her husband or any relative of her husband, and it is shown that she had committed suicide within a period of seven years from the date of her marriage and that her husband or such relative had subjected her to cruelty, the court may presume, having regard to all the other circumstances of the case, that such suicide had been abetted by her husband or such relative.","12","Burden of Proof","Evidence Law",["IEA abetment suicide married woman section 113A husband relative seven years cruelty presume may CrPC"]],
  ["113B","Presumption as to dowry death","When the question is whether a person has committed the dowry death of a woman and it is shown that soon before her death such woman had been subjected by such person to cruelty or harassment for, or in connection with, any demand for dowry, the court shall presume that such person had caused the dowry death. This is a 'shall presume' — mandatory presumption.","12","Burden of Proof","Evidence Law",["IEA dowry death section 113B shall presume cruelty harassment soon before death mandatory presumption accused"]],
  ["114A","Presumption as to absence of consent in certain rape prosecutions","In a prosecution for rape under clauses (a), (b), (c), (d), (e), (f), (g) of sub-section (2) of section 376 IPC, where sexual intercourse by the accused is proved and the question is whether it was without the consent of the woman and such woman states in her evidence that she did not consent, the court shall presume that she did not consent.","12","Burden of Proof","Evidence Law",["IEA rape presumption absence consent section 114A shall presume sexual intercourse proved woman states no consent prosecution"]],
  ["118","Competency to testify","All persons shall be competent to testify unless the court considers that they are prevented from understanding the questions put to them, or from giving rational answers to those questions, by tender years, extreme old age, disease, whether of body or mind, or any other cause of the same kind. A child witness is competent if capable of understanding questions and giving rational answers — no minimum age.","13","Production and Effect of Evidence","Evidence Law",["IEA competency witness section 118 tender years old age disease rational answers child witness minimum age"]],
  ["119","Dumb witnesses","A witness who is unable to speak may give his evidence in any other manner in which he can make it intelligible, as by writing or by signs; but such writing must be written and the signs made in open court and shall be deemed to be oral evidence. Sign language or written response by a mute witness is valid oral evidence.","13","Production and Effect of Evidence","Evidence Law",["IEA dumb witness section 119 unable speak writing signs intelligible open court oral evidence mute"]],
  ["120","Parties to civil suit, husband and wife — competency","In civil proceedings, the parties to the suit, and the husband or wife of any party to the suit, shall be competent witnesses. In criminal proceedings, the accused is a competent witness in his own defence (but not compellable under Art.20(3)). Husband and wife are competent but not compellable for/against each other.","13","Production and Effect of Evidence","Evidence Law",["IEA parties civil criminal competency section 120 husband wife accused defence compellable Article 20(3)"]],
  ["122","Communications during marriage","No person who is or has been married shall be compelled to disclose any communication made to him during marriage by any person to whom he is or has been married; nor shall he be permitted to disclose any such communication, unless the person who made it, or his representative in interest, consents to the disclosure. Marital privilege — protects confidential marital communications.","13","Production and Effect of Evidence","Evidence Law",["IEA marital privilege section 122 communication during marriage compelled disclosure consent representative"]],
  ["124","Official communications","No public officer shall be compelled to disclose communications made to him in official confidence, when he considers that the public interests would suffer by the disclosure. The court cannot compel disclosure. Crown privilege / state privilege — balancing public interest. S.124 bars disclosure of official communications.","13","Production and Effect of Evidence","Evidence Law",["IEA official communications section 124 public officer official confidence public interest state privilege Crown privilege disclosure"]],
  ["126","Professional communications","No barrister, attorney, pleader or vakil shall at any time be permitted, unless with his client's express consent, to disclose any communication made to him in the course and for the purpose of his employment as such barrister, pleader, attorney or vakil, by or on behalf of his client, or to state the contents or condition of any document with which he has become acquainted in the course and for the purpose of his professional employment, or to disclose any advice given by him to his client in the course and for the purpose of such employment.","13","Production and Effect of Evidence","Evidence Law",["IEA legal professional privilege section 126 attorney pleader vakil client communication confidential advice document"]],
  ["132","Witness not excused from answering on ground that answer will criminate him","A witness shall not be excused from answering any question as to any matter relevant to the matter in issue in any suit or in any civil or criminal proceeding, upon the ground that the answer to such question will criminate, or may tend directly or indirectly to criminate, such witness, or that it will expose, or tend directly or indirectly to expose, such witness to a penalty or forfeiture of any kind. But S.132 proviso: no such answer shall subject the witness to any arrest or prosecution.","13","Production and Effect of Evidence","Evidence Law",["IEA compelled answer criminate section 132 witness civil criminal penalty forfeiture proviso no arrest prosecution"]],
  ["137","Examination of witnesses","The examination of a witness by the party who calls him shall be called his examination-in-chief. The examination of a witness by the adverse party shall be called his cross-examination. The examination of a witness, subsequent to the cross-examination by the party who called him, shall be called his re-examination. The order is mandatory: examination-in-chief → cross-examination → re-examination.","14","Examination of Witnesses","Evidence Law",["IEA examination witnesses section 137 examination-in-chief cross-examination re-examination adverse party order mandatory"]],
  ["138","Order of examinations — right of cross-examination","Witnesses shall be first examined-in-chief, then cross-examined if the adverse party so desires, and then re-examined. The examination and cross-examination must relate to relevant facts, but the cross-examination need not be confined to the facts to which the witness testified on his examination-in-chief. Cross-examination is the key tool to test the veracity of a witness.","14","Examination of Witnesses","Evidence Law",["IEA cross-examination section 138 not confined examination-in-chief relevant facts veracity test adverse party right"]],
  ["139","Cross-examination of person called to produce document","A person summoned to produce a document does not become a witness by the mere fact that he produces it, and cannot be cross-examined unless and until he is called as a witness. Mere production of document does not expose a person to cross-examination.","14","Examination of Witnesses","Evidence Law",["IEA cross-examination produce document section 139 not witness mere production called required"]],
  ["142","Leading questions in examination-in-chief","Leading questions must not, if objected to by the adverse party, be asked in an examination-in-chief, or in a re-examination, except with the permission of the court. A leading question is one that suggests the answer expected. However, with leave of court, leading questions may be asked even in examination-in-chief (e.g., for formal introductory matters).","14","Examination of Witnesses","Evidence Law",["IEA leading question section 141 142 examination-in-chief re-examination adverse party objection suggests answer"]],
  ["143","Leading questions in cross-examination","Leading questions may be asked in cross-examination. This is one of the most powerful tools in cross-examination — the counsel can suggest to the witness what the answer should be and the witness must affirm or deny.","14","Examination of Witnesses","Evidence Law",["IEA leading questions cross-examination section 143 suggest answer affirm deny powerful tool"]],
  ["145","Cross-examination as to previous statements in writing","A witness may be cross-examined as to previous statements made by him in writing or reduced into writing, and relevant to matters in question, without such writing being shown to him, or being proved; but if it is intended to contradict him by the writing, his attention must, before the writing can be proved, be called to those parts of it which are to be used for the purpose of contradicting him.","14","Examination of Witnesses","Evidence Law",["IEA cross-examination previous written statements section 145 contradict writing called attention prove"]],
  ["146","Questions lawful in cross-examination","When a witness is cross-examined, he may, in addition to the questions hereinbefore referred to, be asked any questions which tend to: test his veracity; discover who he is and what is his position in life; shake his credit, by injuring his character. Questions to injure character are subject to limitation under S.148 and S.149.","14","Examination of Witnesses","Evidence Law",["IEA cross-examination questions section 146 veracity credit character injure shake S148 S149 limitation"]],
  ["148","Court to decide when question shall be asked","If any such question relates to a matter not relevant to the suit or proceeding, except in so far as it affects the credit of the witness by injuring his character, the court shall decide whether or not the witness shall be compelled to answer it, and may, if it thinks fit, warn the witness that he is not obliged to answer it.","14","Examination of Witnesses","Evidence Law",["IEA court decide compel answer section 148 not relevant credit injure character warn obliged"]],
  ["151","Indecent and scandalous questions","The court may forbid any questions or inquiries which it regards as indecent or scandalous, although such questions or inquiries may have some bearing on the questions before the court, unless they relate to facts in issue, or to matters necessary to be known in order to determine whether or not the facts in issue existed.","14","Examination of Witnesses","Evidence Law",["IEA indecent scandalous questions section 151 court forbid bearing fact in issue necessary determine"]],
  ["153","Exclusion of evidence to contradict answers to questions testing veracity","When a witness has been asked and has answered any question which is relevant to the inquiry only in so far as it tends to shake his credit by injuring his character, no evidence shall be given to contradict him; but, if he answers falsely, he may afterwards be charged with giving false evidence.","14","Examination of Witnesses","Evidence Law",["IEA contradict answers credit character section 153 shake veracity false evidence charged"]],
  ["155","Impeaching credit of witnesses","The credit of a witness may be impeached by the adverse party or, with court's consent, by the party calling him: by showing unworthy of credit; by proof of bribery; by proof of previous inconsistent statements; (if the witness is a woman in rape cases, and with court's leave, proof of general immoral character).","14","Examination of Witnesses","Evidence Law",["IEA impeach credit section 155 bribery inconsistent statements adverse party woman rape court leave immoral"]],
  ["157","Former statements of witness as corroboration","In order to corroborate the testimony of a witness, any former statement made by such witness relating to the same fact, at or about the time when the fact took place, or before any authority legally competent to investigate the fact, may be proved. Example: a statement to police under S.161 CrPC can be used to corroborate oral testimony.","14","Examination of Witnesses","Evidence Law",["IEA corroboration former statement section 157 witness same fact police S161 CrPC authority"]],
  ["158","What matters may be proved in connection with proved statement relevant under section 32 or 33","Whenever any statement, relevant under section 32 or 33, is proved, all matters may be proved either in order to contradict or to corroborate it, or in order to impeach or confirm the credit of the person by whom it was made, which might have been proved if that person had been called as a witness, and had denied upon cross-examination the truth of the matter suggested.","14","Examination of Witnesses","Evidence Law",["IEA statement section 32 33 proved matters corroborate contradict impeach credit S158"]],
];
IEA_DATA.forEach(([sec,title,desc,ch,cht,cat,kw])=>civil.push(e("Indian Evidence Act, 1872","IEA",sec,title,desc,ch,cht,cat,kw)));

// ── Arbitration and Conciliation Act 1996 (extended) ────
const ARB_DATA = [
  ["2","Definitions","'Arbitral award' includes interim award; 'arbitral tribunal' means sole arbitrator or panel; 'arbitration' means any arbitration whether or not administered by permanent arbitral institution; 'arbitration agreement' means agreement referred to in section 7; 'Court' means the principal Civil Court of original jurisdiction in a district, includes High Court in some cases; 'International commercial arbitration' means arbitration where at least one party is foreign.","1","Preliminary","Arbitration / ADR",["Arbitration Act definitions arbitral award tribunal agreement court international commercial section 2"]],
  ["9","Interim measures by court","A party may, before or during arbitral proceedings or at any time after the making of the arbitral award but before it is enforced apply to a court for interim measures of protection. Measures: appointment of guardian for minor; preservation/inspection of goods; securing amount in dispute; detaining property; appointment of receiver; injunction. After 2015 Amendment: court must dispose of S.9 application in 90 days.","2","Arbitration Agreement","Arbitration / ADR",["Arbitration Act interim measures court section 9 guardian goods secure amount receiver injunction 90 days 2015 amendment"]],
  ["11","Appointment of arbitrators by Court","If the appointment procedure fails, Supreme Court (international) or High Court (domestic) shall appoint arbitrator on application. 2019 Amendment: SC/HC may designate an arbitral institution (Arbitral Council of India). Qualification of arbitrator under Seventh Schedule — grounds for ineligibility. Fifth Schedule: grounds for disclosure.","3","Composition of Arbitral Tribunal","Arbitration / ADR",["Arbitration Act appointment arbitrator court section 11 SC HC institution 2019 amendment qualification Fifth Seventh Schedule disclosure ineligibility"]],
  ["12","Grounds for challenge of arbitrator","An arbitrator may be challenged if circumstances give rise to justifiable doubts as to his independence or impartiality, or if he does not possess qualifications agreed to by the parties. A party may challenge an arbitrator appointed by him only for reasons he becomes aware of after the appointment. Fifth Schedule: list of circumstances leading to doubts; Seventh Schedule: arbitrator ineligible.","3","Composition of Arbitral Tribunal","Arbitration / ADR",["Arbitration Act challenge arbitrator section 12 independence impartiality Fifth Seventh Schedule doubts qualify appointed"]],
  ["17","Interim measures ordered by arbitral tribunal","A party may apply to the arbitral tribunal for interim measures. After 2015 Amendment, orders of tribunal under S.17 are enforceable as orders of court. The tribunal has same powers as court under S.9 except appointment of receiver. The 2015 amendment made arbitral tribunal's interim orders enforceable without separate court application.","4","Jurisdiction of Arbitral Tribunal","Arbitration / ADR",["Arbitration Act interim measures tribunal section 17 2015 amendment enforceable court order receiver same power S9"]],
  ["23","Statements of claim and defence","Within the period agreed by the parties or determined by the arbitral tribunal, the claimant shall state the facts supporting his claim, the points at issue and the relief or remedy sought, and the respondent shall state his defence in respect of these particulars. The parties may submit all documents they consider to be relevant or may add a reference to documents or other evidence they will submit.","5","Conduct of Arbitral Proceedings","Arbitration / ADR",["Arbitration Act claim defence section 23 facts issue relief remedy documents evidence parties respondent claimant period"]],
  ["25","Default of a party","Unless otherwise agreed by the parties, where without sufficient cause the claimant fails to communicate his statement of claim in accordance with S.23(1), the arbitral tribunal shall terminate the proceedings. Where the respondent fails to communicate his statement of defence, the tribunal may continue proceedings and make award on evidence before it.","5","Conduct of Arbitral Proceedings","Arbitration / ADR",["Arbitration Act default party section 25 claimant respondent terminate continue award evidence sufficient cause"]],
  ["28","Rules applicable to substance of dispute","Where the place of arbitration is situate in India: (a) the arbitral tribunal shall decide the dispute in accordance with the substantive law for the time being in force in India; (b) in international commercial arbitration, the rules of law designated by the parties as applicable or determined by the tribunal. Principle: parties can choose governing law.","5","Conduct of Arbitral Proceedings","Arbitration / ADR",["Arbitration Act governing law section 28 India substantive law international commercial parties designate tribunal"]],
  ["29A","Time limit for arbitral award","The award in matters other than international commercial arbitration shall be made within a period of twelve months from the date of completion of pleadings. The period may be extended by six months with consent of parties. Beyond 18 months: only with court leave. Court may reduce fees of arbitrators and impose costs. 2019 Amendment: introduced this section to cure delay.","5","Conduct of Arbitral Proceedings","Arbitration / ADR",["Arbitration Act time limit award section 29A twelve months six months eighteen months court leave fees reduce costs 2019"]],
  ["31","Form and contents of arbitral award","An arbitral award shall be made in writing and shall be signed by the members of the arbitral tribunal. The award shall state the reasons unless parties agreed no reasons or award is on agreed terms. The award shall state its date and the place of arbitration. A copy of the award shall be delivered to each party. Interest at 18% per annum is the default rate under S.31(7) if no agreement on interest.","7","Making of Arbitral Award and Termination of Proceedings","Arbitration / ADR",["Arbitration Act award form section 31 writing signed reasons place date 18 percent interest parties copy delivered"]],
  ["32","Termination of proceedings","The arbitral proceedings are terminated by: final arbitral award; order of the arbitral tribunal under S.32(2). The tribunal shall terminate the proceedings when: claimant withdraws claim (unless respondent objects); parties agree to termination; tribunal finds continuation unnecessary or impossible.","7","Making of Arbitral Award and Termination of Proceedings","Arbitration / ADR",["Arbitration Act termination proceedings section 32 final award withdraw claim agree impossible unnecessary"]],
  ["33","Correction and interpretation of award","Within thirty days of receipt of award, a party with notice may request correction of computational/clerical error, or interpretation of a specific point. Request for additional award for claims omitted: within thirty days. Tribunal may on its own initiative correct within thirty days of making award.","7","Making of Arbitral Award and Termination of Proceedings","Arbitration / ADR",["Arbitration Act correction interpretation section 33 thirty days clerical computational additional award omitted initiative"]],
  ["34A","Setting aside award — Grounds (expanded)","Beyond S.34 grounds, 2019 Amendment inserted S.34(2A): an arbitral award arising out of domestic arbitration may be set aside if it is patently illegal appearing on the face of the award. 'Patently illegal' means: award is contrary to the substantive law; construction of contract is perverse; no foundation of facts for decision; arbitral procedure not followed.","8","Recourse Against Arbitral Award","Arbitration / ADR",["Arbitration Act patently illegal section 34(2A) 2019 amendment domestic award set aside contrary law perverse no facts procedure"]],
  ["37","Appealable orders","An appeal shall lie from the following orders: granting or refusing S.9 interim measures; setting aside or refusing to set aside award under S.34; accepting or rejecting a plea under S.16(2) or S.16(3); granting or refusing S.17 interim order. No second appeal from orders under S.37. Only one appeal allowed.","9","Appeals","Arbitration / ADR",["Arbitration Act appeals section 37 S9 S34 S16 S17 no second appeal orders one appeal only"]],
  ["42A","Confidentiality of information","The arbitrator, the arbitral institution and the parties to the arbitration agreement shall maintain confidentiality of all arbitral proceedings except award where its disclosure is necessary for implementation and enforcement. Introduced by 2019 Amendment. Confidentiality is a key advantage of arbitration over court proceedings.","10","Miscellaneous","Arbitration / ADR",["Arbitration Act confidentiality section 42A 2019 amendment proceedings award disclosure implementation enforcement advantage"]],
  ["43D","Speedy disposal of applications","All applications or appeals filed under the Arbitration Act in the High Court shall be heard and disposed of as expeditiously as possible, and endeavour shall be made to dispose of such proceedings within a period of one year from the date of service of notice on the opposite party.","10","Miscellaneous","Arbitration / ADR",["Arbitration Act speedy disposal section 43D High Court one year notice opposite party expeditiously applications appeals"]],
  ["44","Definition of foreign award","'Foreign award' means an arbitral award on differences between persons arising out of legal relationships, whether contractual or not, considered as commercial under the law in force in India, made on or after the 11th day of October, 1960, in pursuance of an agreement in writing for arbitration to which the New York Convention applies.","11","New York Convention Awards","Arbitration / ADR",["foreign award definition section 44 New York Convention legal relationship commercial October 1960 agreement writing"]],
  ["48","Conditions for enforcement of foreign awards","Enforcement of a foreign award may be refused only if: party was under incapacity or agreement invalid; no proper notice of arbitrator appointment or hearing; award beyond scope of submission; composition of tribunal irregular; award not yet binding or set aside; subject matter not arbitrable under Indian law; award conflicts with public policy of India.","11","New York Convention Awards","Arbitration / ADR",["foreign award enforcement section 48 refuse incapacity notice scope composition binding public policy arbitrable India"]],
  ["61","Application and scope of Conciliation","The provisions of Part III (Conciliation) shall apply to conciliation of disputes arising out of legal relationship, whether contractual or not, and to all proceedings relating thereto. Part III: S.61-81. Conciliation is voluntary; it results in a settlement agreement which has the effect of an arbitral award and is final and binding.","12","Conciliation","Arbitration / ADR",["Arbitration Act conciliation section 61 Part III disputes settlement agreement final binding arbitral award voluntary"]],
  ["74","Legal status and effect of settlement agreement","Where the parties reach agreement on a settlement of the dispute, they shall draw up and sign a written settlement agreement. When signed it is final and binding; enforceable in the same manner as an arbitral award on agreed terms. This makes the conciliation settlement as powerful as an arbitral award for enforcement purposes.","12","Conciliation","Arbitration / ADR",["Arbitration Act settlement agreement section 74 final binding signed enforceable arbitral award agreed terms conciliation"]],
];
ARB_DATA.forEach(([sec,title,desc,ch,cht,cat,kw])=>civil.push(e("Arbitration and Conciliation Act, 1996","ACA",sec,title,desc,ch,cht,cat,kw)));

save('bulk_civil_laws.json', civil);

